// Independent API probe using the installed, version-matched libllama.
#include "llama.h"
#include <algorithm>
#include <cmath>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <iterator>
#include <stdexcept>
#include <vector>

struct observation {
    int position, prefix_last_id, target_id, greedy_id;
    double target_logit, log_partition, logprob, mass;
};

static std::vector<observation> score(llama_context * ctx, const std::vector<llama_token> & ids,
                                       int vocab_size, int batch_size) {
    llama_memory_clear(llama_get_memory(ctx), true);
    llama_batch batch = llama_batch_init(batch_size, 0, 1);
    std::vector<observation> result;
    for (int start = 0; start < int(ids.size()) - 1; start += batch_size) {
        batch.n_tokens = std::min(batch_size, int(ids.size()) - 1 - start);
        for (int j = 0; j < batch.n_tokens; ++j) {
            batch.token[j] = ids[start + j];
            batch.pos[j] = start + j;
            batch.n_seq_id[j] = 1;
            batch.seq_id[j][0] = 0;
            batch.logits[j] = true;
        }
        if (llama_decode(ctx, batch) != 0) throw std::runtime_error("decode failed");
        for (int j = 0; j < batch.n_tokens; ++j) {
            const float * logits = llama_get_logits_ith(ctx, j);
            if (!logits) throw std::runtime_error("missing logits row");
            const int greedy = int(std::max_element(logits, logits + vocab_size) - logits);
            const double peak = logits[greedy];
            double sum = 0;
            for (int k = 0; k < vocab_size; ++k) {
                if (!std::isfinite(logits[k])) throw std::runtime_error("nonfinite raw logit");
                sum += std::exp(double(logits[k]) - peak);
            }
            const double partition = peak + std::log(sum);
            double mass = 0;
            for (int k = 0; k < vocab_size; ++k) mass += std::exp(double(logits[k]) - partition);
            const int pos = start + j + 1, target = ids[pos];
            result.push_back({pos, ids[pos-1], target, greedy, logits[target], partition,
                              double(logits[target]) - partition, mass});
        }
    }
    llama_batch_free(batch);
    return result;
}

static void print_rows(const std::vector<observation> & rows) {
    std::cout << '[';
    for (size_t i = 0; i < rows.size(); ++i) {
        const auto & r = rows[i];
        if (i) std::cout << ',';
        std::cout << "{\"position\":" << r.position << ",\"prefix_last_id\":" << r.prefix_last_id
                  << ",\"target_id\":" << r.target_id << ",\"greedy_id\":" << r.greedy_id
                  << ",\"target_logit\":" << r.target_logit << ",\"log_partition\":" << r.log_partition
                  << ",\"target_logprob\":" << r.logprob << ",\"probability_mass\":" << r.mass << '}';
    }
    std::cout << ']';
}

int main(int argc, char ** argv) {
    if (argc != 4) { std::cerr << "Usage: probe MODEL INPUT_TEXT BACKEND_DIRECTORY\n"; return 2; }
    try {
        std::ifstream input(argv[2], std::ios::binary);
        if (!input) throw std::runtime_error("input unavailable");
        std::string text((std::istreambuf_iterator<char>(input)), std::istreambuf_iterator<char>());
        ggml_backend_load_all_from_path(argv[3]);
        llama_backend_init();
        auto mp = llama_model_default_params();
        mp.n_gpu_layers = -1;
        auto * model = llama_model_load_from_file(argv[1], mp);
        if (!model) throw std::runtime_error("model load failed");
        const auto * vocab = llama_model_get_vocab(model);
        int n = -llama_tokenize(vocab, text.data(), int(text.size()), nullptr, 0, true, true);
        if (n < 2 || n > 64) throw std::runtime_error("probe needs 2 to 64 tokens");
        std::vector<llama_token> ids(n);
        if (llama_tokenize(vocab, text.data(), int(text.size()), ids.data(), n, true, true) != n)
            throw std::runtime_error("tokenization mismatch");
        auto cp = llama_context_default_params();
        cp.n_ctx = 8192; cp.n_batch = 64; cp.n_ubatch = 64; cp.n_seq_max = 1;
        cp.flash_attn_type = LLAMA_FLASH_ATTN_TYPE_AUTO; cp.kv_unified = false;
        auto * ctx = llama_init_from_model(model, cp);
        if (!ctx) throw std::runtime_error("context load failed");
        const int size = llama_vocab_n_tokens(vocab);
        const auto batched = score(ctx, ids, size, 64);
        const auto sequential = score(ctx, ids, size, 1);
        std::cout << std::setprecision(17) << std::boolalpha;
        std::cout << "{\"vocabulary\":" << size << ",\"context\":" << llama_n_ctx(ctx)
                  << ",\"bos_id\":" << llama_vocab_bos(vocab) << ",\"eos_id\":" << llama_vocab_eos(vocab)
                  << ",\"auto_bos\":" << llama_vocab_get_add_bos(vocab)
                  << ",\"auto_eos\":" << llama_vocab_get_add_eos(vocab)
                  << ",\"add_special\":true,\"parse_special\":true,\"first_token_excluded\":true,\"token_ids\":[";
        for (size_t i = 0; i < ids.size(); ++i) { if (i) std::cout << ','; std::cout << ids[i]; }
        std::cout << "],\"batch\":"; print_rows(batched);
        std::cout << ",\"sequential\":"; print_rows(sequential); std::cout << "}\n";
        llama_free(ctx); llama_model_free(model); llama_backend_free();
        return 0;
    } catch (const std::exception & e) {
        std::cerr << e.what() << '\n';
        return 1;
    }
}

